  });

  it("adds a product and reports correct itemCount", () => {
    cart.add(product("a", 500), 2);
    expect(cart.itemCount).toBe(2);
  });

  it("merges quantity when adding same product twice", () => {
    cart.add(product("a", 500), 2);
    cart.add(product("a", 500), 3);
    expect(cart.itemCount).toBe(5);
  });

  it("tracks multiple products independently", () => {
    cart.add(product("a", 500), 1);
    cart.add(product("b", 300), 2);
    expect(cart.itemCount).toBe(3);
  });

  it("rejects non-positive quantity in add", () => {
    expect(() => cart.add(product("a", 500), 0)).toThrow(RangeError);
    expect(() => cart.add(product("a", 500), -1)).toThrow(RangeError);
  });

  it("rejects non-integer quantity in add", () => {
    expect(() => cart.add(product("a", 500), 1.5)).toThrow(RangeError);
  });

  it("rejects negative unit price in add", () => {
    expect(() => cart.add(product("a", -1), 1)).toThrow(RangeError);
  });

  it("remove returns true for existing product", () => {
    cart.add(product("a", 500), 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove returns false for unknown product", () => {
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity changes quantity", () => {
    cart.add(product("a", 500), 2);
    cart.updateQuantity("a", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("updateQuantity with 0 removes the product", () => {
    cart.add(product("a", 500), 2);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
  });

  it("updateQuantity throws for unknown product", () => {
    expect(() => cart.updateQuantity("x", 3)).toThrow("Product x is not in the cart");
  });

  it("updateQuantity rejects negative quantity", () => {
    cart.add(product("a", 500), 1);
