      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const cart = new Cart({
      discountPolicy: discount,
      shippingCalculator: shipping,
      region: "US-CA",
    });
    cart.add(product("a", 1000), 1);
    const result = await cart.checkout({ asyncTaxProvider });
    // subtotal 1000, discount 200, discounted 800, tax 10% of 800 = 80, shipping 500
    expect(result.totals.subtotalCents).toBe(1000);
    expect(result.totals.discountCents).toBe(200);
    expect(result.totals.taxCents).toBe(80);
    expect(result.totals.shippingCents).toBe(500);
    expect(result.totals.totalCents).toBe(800 + 80 + 500);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
  });

  it("propagates asyncTaxProvider failure", async () => {
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("rate service unavailable")),
    };
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
      "rate service unavailable",
    );
  });

  it("combines priceFetcher, inventoryChecker, and asyncTaxProvider", async () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(100),
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(300),
    };
    const cart = new Cart({
      discountPolicy: discount,
      shippingCalculator: shipping,
    });
    cart.add(product("a", 500), 2);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(600),
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.08),
    };

    const result = await cart.checkout({
      priceFetcher,
      inventoryChecker,
      asyncTaxProvider,
    });

    // Updated price: 600 * 2 = 1200 subtotal
    expect(result.totals.subtotalCents).toBe(1200);
    // discount 100, discounted = 1100
    expect(result.totals.discountCents).toBe(100);
    // tax 8% of 1100 = 88
    expect(result.totals.taxCents).toBe(88);
    expect(result.totals.shippingCents).toBe(300);
    expect(result.totals.totalCents).toBe(1100 + 88 + 300);
  });

  it("checks inventory for each line and fails on first denial", async () => {
    const cart = new Cart();
    cart.add(product("a", 500), 1);
    cart.add(product("b", 300), 2);

    const inventoryChecker: InventoryChecker = {
      check: vi
        .fn()
        .mockResolvedValueOnce({ available: true })
        .mockResolvedValueOnce({ available: false, reason: "sold out" }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      expect((err as InventoryError).productId).toBe("b");
    }
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it.each([0, 100, 10000, -50])("returns 0 for subtotal %i", (subtotal) => {
    expect(policy.computeDiscountCents(subtotal)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([-1, 101, NaN, Infinity, -Infinity])(
      "rejects out-of-range percent %s",
      (percent) => {
        expect(() => new PercentageDiscountPolicy(percent)).toThrow(RangeError);
      },
    );

    it.each([0, 50, 100])("accepts valid percent %i", (percent) => {
      expect(() => new PercentageDiscountPolicy(percent)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("computes 10% of 1000 as 100", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(1000)).toBe(100);
    });

    it("rounds down to nearest cent", () => {
      const policy = new PercentageDiscountPolicy(33);
      // 33% of 100 = 33.0 → 33
      expect(policy.computeDiscountCents(100)).toBe(33);
      // 33% of 101 = 33.33 → 33
      expect(policy.computeDiscountCents(101)).toBe(33);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(-500)).toBe(0);
    });

    it("100% discount equals subtotal", () => {
      const policy = new PercentageDiscountPolicy(100);
      expect(policy.computeDiscountCents(5000)).toBe(5000);
    });

    it("0% discount returns 0", () => {
      const policy = new PercentageDiscountPolicy(0);
      expect(policy.computeDiscountCents(5000)).toBe(0);
    });

    it("handles large subtotals", () => {
      const policy = new PercentageDiscountPolicy(15);
      // 15% of 999999 = 149999.85 → 149999
      expect(policy.computeDiscountCents(999999)).toBe(149999);
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it.each([-1, -100])("rejects negative amount %i", (amount) => {
      expect(() => new FixedAmountDiscountPolicy(amount)).toThrow(RangeError);
    });

    it("rejects non-integer amount", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it.each([0, 500])("accepts valid amount %i", (amount) => {
      expect(() => new FixedAmountDiscountPolicy(amount)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns amount when subtotal exceeds it", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(1000)).toBe(500);
    });

    it("caps at subtotal when amount exceeds subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(200)).toBe(200);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("returns exact amount when equal to subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(500)).toBe(500);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "CompositeDiscountPolicy requires at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all child policies against original subtotal", () => {
      const p1 = new PercentageDiscountPolicy(10); // 10% of 1000 = 100
      const p2 = new FixedAmountDiscountPolicy(200); // fixed 200
      const composite = new CompositeDiscountPolicy([p1, p2], "sum");
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(100)],
        "sum",
      );
      expect(composite.computeDiscountCents(-50)).toBe(0);
    });

    it("can exceed subtotal (caller clamps)", () => {
      // 50% of 100 = 50, fixed 80 capped to 100 → sum = 150
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new FixedAmountDiscountPolicy(80)],
        "sum",
      );
      // sum mode: each gets original subtotal. 50% of 100 = 50, min(80,100) = 80 → 130
      expect(composite.computeDiscountCents(100)).toBe(130);
    });

    it("defaults to sum mode when not specified", () => {
      const p1 = new FixedAmountDiscountPolicy(100);
      const p2 = new FixedAmountDiscountPolicy(200);
      const composite = new CompositeDiscountPolicy([p1, p2]);
      expect(composite.computeDiscountCents(500)).toBe(300);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially to remaining subtotal", () => {
      // Start 1000; 10% off → 100 discount, remaining 900; fixed 200 → 200 discount
      // Total discount = 300
      const p1 = new PercentageDiscountPolicy(10);
      const p2 = new FixedAmountDiscountPolicy(200);
      const composite = new CompositeDiscountPolicy([p1, p2], "chain");
      expect(composite.computeDiscountCents(1000)).toBe(300);
    });

    it("order matters in chain mode", () => {
      // Order A: fixed 200 first (remaining 800), then 10% of 800 = 80 → total 280
      const compositeA = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(200), new PercentageDiscountPolicy(10)],
        "chain",
      );
      // Order B: 10% first (100, remaining 900), then fixed 200 → total 300
      const compositeB = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "chain",
      );
      expect(compositeA.computeDiscountCents(1000)).toBe(280);
      expect(compositeB.computeDiscountCents(1000)).toBe(300);
    });

    it("stops accumulating when remaining hits 0", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(500),
          new FixedAmountDiscountPolicy(500),
          new FixedAmountDiscountPolicy(500),
        ],
        "chain",
      );
      // 500 capped to 500 (remaining 0), next steps do 0
      expect(composite.computeDiscountCents(500)).toBe(500);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(100)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });
});

