const product = (id: string, priceCents: number, weightGrams = 0): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents: priceCents,
  weightGrams,
});

describe("Cart – line management", () => {
  let cart: Cart;

  beforeEach(() => {
    cart = new Cart();
  });

  it("adds a product and reports correct itemCount", () => {
    cart.add(product("a", 500), 2);
    expect(cart.itemCount).toBe(2);
  });

  it("merges quantity when adding same product twice", () => {
    cart.add(product("a", 500), 2);
    cart.add(product("a", 500), 3);
    expect(cart.itemCount).toBe(5);
  });

  it("tracks multiple products independently", () => {
    cart.add(product("a", 500), 1);
    cart.add(product("b", 300), 2);
    expect(cart.itemCount).toBe(3);
  });

  it("rejects non-positive quantity in add", () => {
    expect(() => cart.add(product("a", 500), 0)).toThrow(RangeError);
    expect(() => cart.add(product("a", 500), -1)).toThrow(RangeError);
  });

  it("rejects non-integer quantity in add", () => {
    expect(() => cart.add(product("a", 500), 1.5)).toThrow(RangeError);
  });

  it("rejects negative unit price in add", () => {
    expect(() => cart.add(product("a", -1), 1)).toThrow(RangeError);
  });

  it("remove returns true for existing product", () => {
    cart.add(product("a", 500), 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove returns false for unknown product", () => {
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity changes quantity", () => {
    cart.add(product("a", 500), 2);
    cart.updateQuantity("a", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("updateQuantity with 0 removes the product", () => {
    cart.add(product("a", 500), 2);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
  });

  it("updateQuantity throws for unknown product", () => {
    expect(() => cart.updateQuantity("x", 3)).toThrow("Product x is not in the cart");
  });

  it("updateQuantity rejects negative quantity", () => {
    cart.add(product("a", 500), 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("updateQuantity rejects non-integer quantity", () => {
    cart.add(product("a", 500), 1);
    expect(() => cart.updateQuantity("a", 2.5)).toThrow(RangeError);
  });

  it("clear empties the cart", () => {
    cart.add(product("a", 500), 2);
    cart.add(product("b", 300), 1);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot returns deep copies", () => {
    cart.add(product("a", 500), 2);
    const snap = cart.snapshot();
    snap[0]!.quantity = 999;
    snap[0]!.product.unitPriceCents = 0;
    // Original cart unaffected
    expect(cart.itemCount).toBe(2);
    expect(cart.snapshot()[0]!.product.unitPriceCents).toBe(500);
  });
});

describe("Cart – pricing pipeline", () => {
  it("computes correct subtotal", () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2); // 2000
    cart.add(product("b", 500), 3); // 1500
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(3500);
  });

  it("empty cart has zero totals", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(0);
    expect(totals.discountCents).toBe(0);
    expect(totals.taxCents).toBe(0);
    expect(totals.shippingCents).toBe(0);
    expect(totals.totalCents).toBe(0);
  });

  it("applies discount policy and clamps to subtotal", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(9999),
    };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(product("a", 1000), 1);
    const totals = cart.totals();
    // Clamped: discount can't exceed subtotal of 1000
    expect(totals.discountCents).toBe(1000);
    expect(totals.totalCents).toBe(0);
  });

  it("clamps negative discount to 0", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(-500),
    };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(product("a", 1000), 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(0);
  });

  it("computes tax on discounted subtotal", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(80),
    };
    const cart = new Cart({ discountPolicy: discount, taxCalculator: tax });
    cart.add(product("a", 1000), 1);
    const totals = cart.totals();
    // Tax called with discountedSubtotal = 1000 - 200 = 800
    expect(tax.computeTaxCents).toHaveBeenCalledWith(800, "US");
    expect(totals.taxCents).toBe(80);
  });

  it("clamps negative tax to 0", () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(-50),
    };
    const cart = new Cart({ taxCalculator: tax });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("passes lines and discounted subtotal to shipping calculator", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(300),
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({
      discountPolicy: discount,
      shippingCalculator: shipping,
    });
    cart.add(product("a", 1000), 1);
    const totals = cart.totals();
    expect(shipping.computeShippingCents).toHaveBeenCalledWith(
      expect.any(Array),
      700, // discounted subtotal
    );
    expect(totals.shippingCents).toBe(500);
  });

  it("clamps negative shipping to 0", () => {
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(-100),
    };
    const cart = new Cart({ shippingCalculator: shipping });
    cart.add(product("a", 1000), 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("totalCents = discountedSubtotal + tax + shipping", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(100),
    };
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(72),
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const cart = new Cart({
      discountPolicy: discount,
      taxCalculator: tax,
      shippingCalculator: shipping,
    });
    cart.add(product("a", 1000), 1);
    const totals = cart.totals();
    // subtotal 1000, discount 100, discounted 900, tax 72, shipping 500
    expect(totals.totalCents).toBe(900 + 72 + 500);
  });

  it("uses configured region for tax", () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: tax, region: "FR" });
    cart.add(product("a", 1000), 1);
    cart.totals();
    expect(tax.computeTaxCents).toHaveBeenCalledWith(1000, "FR");
  });

  it("defaults to US region", () => {
    const tax: TaxCalculator = {
      computeTaxCents: vi.fn().mockReturnValue(0),
    };
    const cart = new Cart({ taxCalculator: tax });
    cart.add(product("a", 1000), 1);
    cart.totals();
    expect(tax.computeTaxCents).toHaveBeenCalledWith(1000, "US");
  });
});

describe("Cart – checkout()", () => {
  it("returns totals and lines for simple checkout", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(1000);
    expect(result.lines).toHaveLength(1);
  });

  it("refreshes prices via priceFetcher", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1500),
    };
    const result = await cart.checkout({ priceFetcher });
    expect(result.totals.subtotalCents).toBe(3000); // 1500 * 2
    expect(result.lines[0]!.product.unitPriceCents).toBe(1500);
  });

  it("throws InventoryError when item unavailable", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: false, reason: "discontinued" }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InstanceType<typeof InventoryError>;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(5);
      expect(invErr.message).toBe("discontinued");
    }
  });

  it("throws InventoryError for partial-stock denial", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 10);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const invErr = err as InstanceType<typeof InventoryError>;
      expect(invErr.productId).toBe("a");
      expect(invErr.requested).toBe(10);
      expect(invErr.available).toBe(3);
    }
  });

  it("passes inventory check when available and quantity sufficient", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 5 }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("passes inventory check when availableQuantity not provided", async () => {
    const cart = new Cart();
    cart.add(product("a", 1000), 2);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("uses asyncTaxProvider for tax computation", async () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(200),
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const cart = new Cart({
      discountPolicy: discount,
      shippingCalculator: shipping,
      region: "US-CA",
    });
    cart.add(product("a", 1000), 1);
    const result = await cart.checkout({ asyncTaxProvider });
    // subtotal 1000, discount 200, discounted 800, tax 10% of 800 = 80, shipping 500
    expect(result.totals.subtotalCents).toBe(1000);
    expect(result.totals.discountCents).toBe(200);
    expect(result.totals.taxCents).toBe(80);
    expect(result.totals.shippingCents).toBe(500);
    expect(result.totals.totalCents).toBe(800 + 80 + 500);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
  });

  it("propagates asyncTaxProvider failure", async () => {
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("rate service unavailable")),
    };
    const cart = new Cart();
    cart.add(product("a", 1000), 1);
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
      "rate service unavailable",
    );
  });

  it("combines priceFetcher, inventoryChecker, and asyncTaxProvider", async () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: vi.fn().mockReturnValue(100),
    };
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(300),
    };
    const cart = new Cart({
      discountPolicy: discount,
      shippingCalculator: shipping,
    });
    cart.add(product("a", 500), 2);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(600),
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 10 }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.08),
    };

    const result = await cart.checkout({
      priceFetcher,
      inventoryChecker,
      asyncTaxProvider,
    });

    // Updated price: 600 * 2 = 1200 subtotal
    expect(result.totals.subtotalCents).toBe(1200);
    // discount 100, discounted = 1100
    expect(result.totals.discountCents).toBe(100);
    // tax 8% of 1100 = 88
    expect(result.totals.taxCents).toBe(88);
    expect(result.totals.shippingCents).toBe(300);
    expect(result.totals.totalCents).toBe(1100 + 88 + 300);
  });

  it("checks inventory for each line and fails on first denial", async () => {
    const cart = new Cart();
    cart.add(product("a", 500), 1);
    cart.add(product("b", 300), 2);

    const inventoryChecker: InventoryChecker = {
      check: vi
        .fn()
        .mockResolvedValueOnce({ available: true })
        .mockResolvedValueOnce({ available: false, reason: "sold out" }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.fail("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      expect((err as InventoryError).productId).toBe("b");
    }
  });
});
"}

